"use client";

import React, { useState, useEffect } from 'react';
import { motion} from "framer-motion";
import { Sparkles, RotateCcw, Plus, Minus } from 'lucide-react';
import { cn } from "@/lib/utils";

export interface InteractiveMobileLoaderWaterTankProps extends React.HTMLAttributes<HTMLDivElement> {
  value?: number; // initial progress, 0 to 100
  title?: string;
  subtitle?: string;
  tankColor1?: string; // primary wave fill
  tankColor2?: string; // offset wave fill
}

export const InteractiveMobileLoaderWaterTank: React.FC<InteractiveMobileLoaderWaterTankProps> = ({
  value = 45,
  title = "Volumetric Fluid Tank",
  subtitle = "Observe the double-layered SVG sinus waves ripple horizontally while the fluid volume rises or falls matching progress changes.",
  tankColor1 = "#3b82f6", // blue
  tankColor2 = "#60a5fa", // lighter blue
  className,
  ...props
}) => {
  const [progress, setProgress] = useState(value);
  const [mounted, setMounted] = useState(false);
  const prefersReducedMotion = usePrefersReducedMotion();

  useEffect(() => {
    setMounted(true);
  }, []);

  // Sync prop changes if any
  useEffect(() => {
    setProgress(value);
  }, [value]);

  const handleIncrement = (amount: number) => {
    setProgress(prev => Math.min(100, Math.max(0, prev + amount)));
  };

  const handleReset = () => {
    setProgress(0);
  };

  // Convert progress (0-100) into y coordinate (100% at bottom to 0% at top)
  const waveYPercent = 100 - progress;

  if (!mounted) {
    return (
      <div className={cn("w-full py-16 text-center text-muted-foreground bg-background", className)}>
        <span>Loading volumetric tank...</span>
      </div>
    );
  }

  return (
    <div
      className={cn(
        "w-full bg-background text-foreground py-16 px-4 md:px-8 max-w-md mx-auto flex flex-col items-center",
        className
      )}
      {...props}
    >
      {/* Header section */}
      <div className="text-center mb-8">
        <span className="text-[10px] font-black uppercase tracking-widest text-primary bg-primary/10 px-3 py-1.5 rounded-full inline-flex items-center gap-1.5 mb-3">
          <Sparkles className="w-3.5 h-3.5 animate-pulse" />
          <span>Vector Liquid Progress</span>
        </span>
        <h3 className="text-xl font-extrabold tracking-tight">{title}</h3>
        <p className="text-[10px] sm:text-xs text-muted-foreground mt-2 leading-relaxed max-w-xs mx-auto">{subtitle}</p>
      </div>

      {/* Volumetric Water Tank Wrapper */}
      <div className="relative w-48 h-48 rounded-full border-[6px] border-muted/80 flex items-center justify-center shadow-lg bg-muted/20 select-none mb-8">

        {/* Core clipping container */}
        <div className="absolute inset-1 rounded-full overflow-hidden bg-card/60 backdrop-blur-sm z-0">

          {/* Waves layer */}
          <motion.div
            className="absolute inset-0 w-full h-full"
            initial={{ y: "100%" }}
            animate={{ y: `${waveYPercent}%` }}
            transition={{ type: "spring", stiffness: 60, damping: 15 }}
          >
            {/* Double wave SVG container */}
            <svg 
              className="absolute bottom-0 w-[200%] h-full left-0 overflow-visible" 
              viewBox="0 0 200 100" 
              preserveAspectRatio="none"
            >
              {/* Back Wave (slower, offset frequency) */}
              <motion.path
                d="M 0 40 Q 25 32, 50 40 T 100 40 T 150 40 T 200 40 L 200 200 L 0 200 Z"
                fill={tankColor2}
                opacity="0.45"
                animate={prefersReducedMotion ? {} : { x: [-100, 0] }}
                transition={{ repeat: Infinity, duration: 4.5, ease: "linear" }}
              />

              {/* Front Wave (faster, deeper ripple) */}
              <motion.path
                d="M 0 40 Q 25 48, 50 40 T 100 40 T 150 40 T 200 40 L 200 200 L 0 200 Z"
                fill={tankColor1}
                opacity="0.85"
                animate={prefersReducedMotion ? {} : { x: [0, -100] }}
                transition={{ repeat: Infinity, duration: 3, ease: "linear" }}
              />
            </svg>
          </motion.div>
        </div>

        {/* Center floating percentage */}
        <div className="relative z-10 text-center pointer-events-none drop-shadow">
          <span className="text-4xl font-black tracking-tighter text-foreground">{progress}%</span>
          <span className="block text-[8px] font-black uppercase text-muted-foreground tracking-widest mt-1">
            {progress === 100 ? "TANK FULL" : progress === 0 ? "EMPTY TANK" : "FILLING LEVEL"}
          </span>
        </div>

        {/* Dynamic circular glowing border overlay */}
        <svg className="absolute inset-[-6px] w-[calc(100%+12px)] h-[calc(100%+12px)] pointer-events-none z-20">
          <circle
            cx="102"
            cy="102"
            r="93"
            stroke="url(#tank-glowing-grad)"
            strokeWidth="3.5"
            fill="none"
            strokeDasharray="585"
            strokeDashoffset={585 - (585 * progress) / 100}
            className="transition-all duration-300 origin-center -rotate-90"
          />
          <defs>
            <linearGradient id="tank-glowing-grad" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stopColor={tankColor2} />
              <stop offset="100%" stopColor={tankColor1} />
            </linearGradient>
          </defs>
        </svg>
      </div>

      {/* Manual interactive buttons panel */}
      <div className="w-full flex items-center justify-between gap-3 bg-muted/40 border border-border/40 p-3 rounded-2xl">
        <div className="flex items-center gap-1.5">
          <button
            type="button"
            onClick={() => handleIncrement(-10)}
            className="w-8 h-8 rounded-lg bg-card border border-border/60 hover:bg-muted text-muted-foreground hover:text-foreground flex items-center justify-center transition-colors cursor-pointer"
            aria-label="Decrement progress by 10"
          >
            <Minus className="w-3.5 h-3.5" />
          </button>

          <button
            type="button"
            onClick={() => handleIncrement(10)}
            className="w-8 h-8 rounded-lg bg-card border border-border/60 hover:bg-muted text-muted-foreground hover:text-foreground flex items-center justify-center transition-colors cursor-pointer"
            aria-label="Increment progress by 10"
          >
            <Plus className="w-3.5 h-3.5" />
          </button>
        </div>

        <span className="text-[9px] font-black uppercase text-muted-foreground tracking-widest shrink-0">
          Manual Calibration
        </span>

        <button
          type="button"
          onClick={handleReset}
          className="px-3.5 py-1.5 rounded-lg bg-card hover:bg-muted border border-border/60 text-[9px] font-black text-muted-foreground hover:text-foreground flex items-center gap-1 transition-colors cursor-pointer"
        >
          <RotateCcw className="w-3 h-3" />
          <span>Reset</span>
        </button>
      </div>
    </div>
  );
};

// Accessible prefers motion
const usePrefersReducedMotion = (): boolean => {
  const [prefersReducedMotion, setPrefersReducedMotion] = React.useState(false);

  React.useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    setPrefersReducedMotion(mediaQuery.matches);

    const listener = (event: MediaQueryListEvent) => {
      setPrefersReducedMotion(event.matches);
    };

    mediaQuery.addEventListener('change', listener);
    return () => {
      mediaQuery.removeEventListener('change', listener);
    };
  }, []);

  return prefersReducedMotion;
};
